"""Frozen public calibration/evaluation of a bilateral-context ligature loss.

Run from the repository root, on PYTHONPATH. No manuscript input is read.
"""
import argparse
import hashlib
import json
import math
import random
from collections import Counter, defaultdict
from pathlib import Path

from vs import refcorpus
from original_triplet import Score

ROOT = Path(__file__).resolve().parent
PLAN_BYTES = (ROOT / 'plan.json').read_bytes()
PLAN = json.loads(PLAN_BYTES)
PLAN_HASH = hashlib.sha256(PLAN_BYTES).hexdigest()
METHODS = ('left_js', 'bilateral_js', 'eight_rule_prose')
TOL = 1e-12


def js(p, q):
    np, nq = sum(p.values()), sum(q.values())
    if not np or not nq:
        raise ValueError('empty context distribution')
    total = 0.0
    for symbol in sorted(p.keys() | q.keys()):
        x, y = p[symbol] / np, q[symbol] / nq
        midpoint = (x + y) / 2
        if x:
            total += x * math.log2(x / midpoint) / 2
        if y:
            total += y * math.log2(y / midpoint) / 2
    return total


class Context:
    def __init__(self, text):
        self.count = Counter(text)
        self.incoming, self.outgoing = defaultdict(Counter), defaultdict(Counter)
        for a, b in zip(text, text[1:]):
            self.incoming[b][a] += 1
            self.outgoing[a][b] += 1
        self.baseline = Score(text)

    def eligible(self, c, a, b):
        return all(self.count[s] >= 40 and self.incoming[s] and self.outgoing[s] for s in (c, a, b))

    def scores(self, c, a, b):
        left = js(self.incoming[c], self.incoming[a])
        right = js(self.outgoing[c], self.outgoing[b])
        return {'left_js': left, 'bilateral_js': (left + right) / 2,
                'eight_rule_prose': self.baseline.total((c, a, b), 'prose')}


def source(language, partition):
    loader = {'calibration': refcorpus.calib_text, 'evaluation': refcorpus.control_text,
              'training': refcorpus.train_text}[partition]
    text = ' '.join(loader(language))
    if partition == 'evaluation':
        text = text[40000:].split(' ', 1)[1]
    return ' ' + text[:40000].rsplit(' ', 1)[0] + ' '


def matching_pool(text, target, decoy, mode, seed):
    groups = defaultdict(lambda: ([], []))
    offset = 0
    for word in text.split(' '):
        for i in range(len(word)-1):
            pair = word[i:i+2]
            if pair not in (target, decoy):
                continue
            start = offset+i
            key = (i == 0, i+2 == len(word))
            if mode in ('left', 'both'):
                key += (text[start-1],)
            if mode == 'both':
                key += (text[start+2],)
            groups[key][pair == decoy].append(start)
        offset += len(word)+1
    rng = random.Random(seed)
    blocked, pairs = set(), []
    for key, (true, wrong) in sorted(groups.items()):
        rng.shuffle(true)
        rng.shuffle(wrong)
        for i, j in zip(true, wrong):
            if abs(i-j) < 3 or i in blocked or j in blocked:
                continue
            pairs.append((i, j))
            blocked.update(range(i-2, i+3))
            blocked.update(range(j-2, j+3))
    rng.shuffle(pairs)
    return pairs


def plant(text, pairs):
    edits = {i: 'X' for i, _ in pairs} | {j: 'Z' for _, j in pairs}
    result, pos = [], 0
    while pos < len(text):
        if pos in edits:
            result.append(edits[pos])
            pos += 2
        else:
            result.append(text[pos])
            pos += 1
    return ''.join(result)


def paired_rows(partition):
    rows, sources = [], []
    for language, contrasts in PLAN['contrasts'].items():
        text = source(language, partition)
        sources.append({'language': language, 'partition': partition, 'characters': len(text),
                        'sha256': hashlib.sha256(text.encode()).hexdigest()})
        for target, decoy in contrasts:
            for mode in PLAN['matching_modes']:
                for seed in PLAN['seeds']:
                    pool = matching_pool(text, target, decoy, mode, seed)
                    for fraction in PLAN['fractions']:
                        pairs = pool[:len(pool)//2] if fraction == .5 else pool
                        if not pairs:
                            rows.append({'language': language, 'partition': partition, 'target': target,
                                         'decoy': decoy, 'mode': mode, 'seed': seed, 'fraction': fraction,
                                         'eligible': False, 'pairs': 0})
                            continue
                        encoded = plant(text, pairs)
                        calculator = Context(encoded)
                        assert calculator.count['X'] == calculator.count['Z'] == len(pairs)
                        for i, j in pairs:
                            assert text[i:i+2] == target and text[j:j+2] == decoy
                            assert (text[i-1] == ' ', text[i+2] == ' ') == (text[j-1] == ' ', text[j+2] == ' ')
                            if mode in ('left', 'both'):
                                assert text[i-1] == text[j-1]
                            if mode == 'both':
                                assert text[i+2] == text[j+2]
                        if mode in ('left', 'both'):
                            assert calculator.incoming['X'] == calculator.incoming['Z']
                        if mode == 'both':
                            assert calculator.outgoing['X'] == calculator.outgoing['Z']
                        sx, sz = calculator.scores('X', *target), calculator.scores('Z', *target)
                        if mode in ('left', 'both'):
                            assert abs(sx['left_js']-sz['left_js']) <= TOL
                        if mode == 'both':
                            assert all(abs(sx[k]-sz[k]) <= TOL for k in METHODS)
                        rows.append({'language': language, 'partition': partition, 'target': target,
                                     'decoy': decoy, 'mode': mode, 'seed': seed, 'fraction': fraction,
                                     'pairs': len(pairs), 'pool': len(pool),
                                     'eligible': bool(calculator.eligible('X', *target) and calculator.eligible('Z', *target)),
                                     'scores': {'X': sx, 'Z': sz}})
    return rows, sources


def primary(rows):
    return [r for r in rows if r['eligible'] and r['mode'] == 'left' and r['fraction'] == 1]


def accepted(score, cutoff):
    return cutoff is not None and score < cutoff-TOL


def summarize(rows, thresholds):
    summary = []
    for mode in PLAN['matching_modes']:
        for fraction in PLAN['fractions']:
            selected = [r for r in rows if r['mode'] == mode and r['fraction'] == fraction]
            eligible = [r for r in selected if r['eligible']]
            row = {'mode': mode, 'fraction': fraction, 'attempted': len(selected),
                   'eligible': len(eligible), 'methods': {}}
            for method in METHODS:
                tally = Counter({'genuine_win': 0, 'decoy_win': 0, 'tie': 0, 'accepted_X': 0, 'accepted_Z': 0})
                for r in eligible:
                    x, z = r['scores']['X'][method], r['scores']['Z'][method]
                    tally['genuine_win' if x < z-TOL else 'decoy_win' if z < x-TOL else 'tie'] += 1
                    tally['accepted_X'] += accepted(x, thresholds[method])
                    tally['accepted_Z'] += accepted(z, thresholds[method])
                row['methods'][method] = dict(tally)
            summary.append(row)
    return summary


def sample_letters(text, language, origin, sample, thresholds):
    calc = Context(text)
    rows = []
    for target, _ in PLAN['contrasts'][language]:
        considered = []
        for c in sorted(calc.count):
            if not c.islower() or c in target or not calc.eligible(c, *target):
                continue
            scores = calc.scores(c, *target)
            considered.append({'candidate': c, 'scores': scores,
                               'accepted': {m: accepted(scores[m], thresholds[m]) for m in METHODS}})
        rows.append({'language': language, 'origin': origin, 'sample': sample,
                     'target': target, 'characters': len(text),
                     'sha256': hashlib.sha256(text.encode()).hexdigest(), 'candidates': considered})
    return rows


def negative_controls(thresholds):
    rows = []
    for language in PLAN['contrasts']:
        rows += sample_letters(source(language, 'evaluation'), language, 'natural', None, thresholds)
        train = source(language, 'training').strip()
        outgoing = defaultdict(Counter)
        for a, b in zip(train, train[1:]):
            outgoing[a][b] += 1
        start_counts = Counter(w[0] for w in train.split())
        def draw(rng, counts):
            point = rng.randrange(sum(counts.values()))
            for symbol, n in sorted(counts.items()):
                if point < n:
                    return symbol
                point -= n
            raise AssertionError('draw failed')
        for seed in PLAN['chain_seeds']:
            rng = random.Random(seed)
            text = [draw(rng, start_counts)]
            while len(text) < 40000:
                options = outgoing[text[-1]]
                if len(text) == 39999:
                    options = Counter({s: n for s, n in options.items() if s != ' '})
                text.append(draw(rng, options or start_counts))
            text = ''.join(text)
            assert '  ' not in text and text[-1] != ' '
            rows += sample_letters(text, language, 'direct_chain', seed, thresholds)
    return rows


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('phase', choices=('calibrate', 'evaluate'))
    args = parser.parse_args()
    if args.phase == 'calibrate':
        rows, sources = paired_rows('calibration')
        eligible = primary(rows)
        thresholds = {}
        for method in METHODS:
            negatives = sorted(r['scores']['Z'][method] for r in eligible)
            thresholds[method] = negatives[math.floor(.05*len(negatives))] if negatives else None
        output = {'plan_sha256': PLAN_HASH, 'script_sha256': hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),
                  'thresholds': thresholds, 'threshold_negative_count': len(eligible),
                  'sources': sources, 'summary': summarize(rows, thresholds), 'paired_rows': rows}
        filename = 'calibration.json'
    else:
        frozen_bytes = (ROOT / 'calibration.json').read_bytes()
        frozen = json.loads(frozen_bytes)
        assert frozen['plan_sha256'] == PLAN_HASH
        assert frozen['script_sha256'] == hashlib.sha256(Path(__file__).read_bytes()).hexdigest()
        rows, sources = paired_rows('evaluation')
        output = {'plan_sha256': PLAN_HASH, 'calibration_sha256': hashlib.sha256(frozen_bytes).hexdigest(),
                  'sources': sources, 'thresholds': frozen['thresholds'],
                  'summary': summarize(rows, frozen['thresholds']), 'paired_rows': rows,
                  'negative_controls': negative_controls(frozen['thresholds'])}
        filename = 'evaluation.json'
    (ROOT / filename).write_text(json.dumps(output, indent=2), encoding='utf-8')
    print(json.dumps({'phase': args.phase, 'primary_eligible': len(primary(rows)),
                      'thresholds': output['thresholds'], 'summary': output['summary']}, indent=2))


if __name__ == '__main__':
    main()

