"""Public calibration of Matlach et al.'s eight-rule triplet score."""
import json
import math
import random
from bisect import bisect_right
from collections import Counter, defaultdict
from itertools import product

from vs import corpus, refcorpus

PROPORTION = 500 / 229431
WEIGHTS = (1, 100, 1, 1, 100, 1, 1, 10)
THRESHOLD = 0.05
LIMIT = 40000
CONTRASTS = {
    'english': [('th', 'to'), ('ea', 'er')],
    'latin': [('en', 'es'), ('pa', 'pe')],
    'italian': [('ch', 'co'), ('de', 'di')],
}
RATES = ((1, 4), (1, 2), (1, 1))
DRAFT_TRIPLETS = [('m','i','d'),('q','i','e'),('f','i','d'),('n','i',' '),('g','c','d')]


def glyph_counts(text):
    return Counter(text), Counter(zip(text, text[1:]))


def correlation(x, y):
    n = len(x)
    if n < 2:
        return 0.0
    mx, my = sum(x) / n, sum(y) / n
    xv = [a - mx for a in x]
    yv = [b - my for b in y]
    den = math.sqrt(sum(a*a for a in xv) * sum(b*b for b in yv))
    return min(1.0, abs(sum(a*b for a,b in zip(xv,yv)) / den)) if den else 0.0


class Score:
    def __init__(self, text, *, single_context_loss=0.0):
        count, raw = glyph_counts(text)
        rows, cols = Counter(), Counter()
        for (a, b), n in raw.items():
            rows[a] += n
            cols[b] += n
        kept = {pair: n for pair,n in raw.items()
                if 500*n >= rows[pair[0]] and 500*n >= cols[pair[1]]}
        self.p = {s: n / len(text) for s,n in count.items()}
        self.m = {edge: n / (len(text)-1) for edge,n in kept.items()}
        self.max_p = max(self.p.values())
        self.max_m = max(self.m.values())
        self.max_diag = max((value for (a,b),value in self.m.items() if a == b), default=1.0)
        self.alphabet = sorted(s for s,p in self.p.items() if s != ' ' and p > PROPORTION)
        self.context = {}
        self.context_sizes = {}
        for c,a in product(count, repeat=2):
            less, more = (a,c) if self.p[a] < self.p[c] else (c,a)
            order = [s for s in sorted(count) if (s,less) in self.m]
            rare = [self.m[s,less] for s in order]
            common = [self.m.get((s,more),0.0) for s in order]
            match = sum(r for r,v in zip(rare,common) if v)
            miss = sum(r for r,v in zip(rare,common) if not v)
            size = len(order)
            distribution = 1.0-correlation(rare,common) if size >= 2 else single_context_loss if size else 0.0
            self.context[c,a] = (match, miss, distribution)
            self.context_sizes[c,a] = size

    def losses(self, c,a,b, version):
        pc, pa, pb = self.p[c], self.p[a], self.p[b]
        matched, unmatched, distribution = self.context[c,a]
        return (
            max(0.0, pc-max(pa,pb))/self.max_p,
            self.m.get((a,b),0.0)/self.max_m,
            matched if version == 'literal' else unmatched,
            distribution,
            self.m.get((c,c),0.0)/self.max_diag,
            (1-min(pa,pb))/self.max_p if version == 'literal' else 1-min(pa,pb)/self.max_p,
            pc/((pa+pc)*(pb+pc)),
            float(a==b),
        )

    def total(self, triplet, version):
        return sum(w*x for w,x in zip(WEIGHTS,self.losses(*triplet,version)))

    def ranker(self, version):
        scores = sorted(self.total((c,a,b),version)
                        for c,a,b in product(self.alphabet, repeat=3) if c not in (a,b))

        def rank(triplet):
            if not all(s in self.p for s in triplet):
                return None
            t = self.total(triplet,version)
            return {
                'rank': bisect_right(scores,t)/len(scores),
                'loss': t,
                'competing': all(s in self.alphabet for s in triplet),
                'loss_left_context_rules': list(self.losses(*triplet,version)[2:4]),
                'rarer_left_contexts': self.context_sizes[triplet[0],triplet[1]],
            }

        return rank


def start_positions(text, first, second, by_left):
    groups = defaultdict(lambda: ([], []))
    offset = 0
    for word in text.split(' '):
        for i in range(len(word)-1):
            couple = word[i:i+2]
            if couple in (first,second):
                # Share a word-initial/medial and a word-final/medial position class.
                key = (i == 0, i+2 == len(word))
                if by_left:
                    key += (word[i-1] if i else ' ',)
                groups[key][couple == second].append(offset+i)
        offset += len(word)+1
    return groups


def paired_positions(text, target, decoy, by_left, seed):
    groups = start_positions(text, target, decoy, by_left)
    rng = random.Random(seed)
    occupied = set()
    paired = []
    for key,(left,right) in sorted(groups.items()):
        rng.shuffle(left)
        rng.shuffle(right)
        for i,j in zip(left,right):
            # Each edit consumes i and i+1 and must have an unedited neighbor.
            if abs(i-j) < 3 or i in occupied or j in occupied:
                continue
            occupied.update(range(i-2,i+3))
            occupied.update(range(j-2,j+3))
            paired.append((i,j))
    rng.shuffle(paired)
    return paired


def encode(text, pairs):
    edits = sorted([(i,'X') for i,j in pairs] + [(j,'Z') for i,j in pairs])
    fragments = []
    after = 0
    for start, symbol in edits:
        fragments.extend((text[after:start],symbol))
        after = start+2
    fragments.append(text[after:])
    return ''.join(fragments)


def euler_surrogate(text, seed):
    outgoing = defaultdict(list)
    for a,b in zip(text,text[1:]):
        outgoing[a].append(b)
    rng = random.Random(seed)
    for a in sorted(outgoing):
        rng.shuffle(outgoing[a])
    stack = [text[0]]
    path = []
    while stack:
        v = stack[-1]
        if outgoing[v]:
            stack.append(outgoing[v].pop())
        else:
            path.append(stack.pop())
    result = ''.join(reversed(path))
    assert len(result) == len(text)
    assert glyph_counts(result) == glyph_counts(text)
    return result


def fixed_match_tests():
    rows = []
    euler = []
    for lang, contrasts in CONTRASTS.items():
        for partition, loader in (('train',refcorpus.train_text),('control',refcorpus.control_text)):
            text = (' ' + ' '.join(loader(lang))[:LIMIT].rsplit(' ',1)[0] + ' ')
            for index,(target,decoy) in enumerate(contrasts):
                for match in ('word_slots','word_slots_and_left'):
                    paired = paired_positions(text,target,decoy,match == 'word_slots_and_left',9141+index)
                    for num,den in RATES:
                        used = paired[:len(paired)*num//den]
                        if not used:
                            continue
                        trial_text = encode(text,used)
                        count, bigrams = glyph_counts(trial_text)
                        assert count['X'] == count['Z'] == len(used)
                        assert bigrams['X','X'] == bigrams['Z','Z'] == 0
                        incoming_delta = sum(abs(bigrams[s,'X']-bigrams[s,'Z']) for s in count)
                        outgoing_delta = sum(abs(bigrams['X',s]-bigrams['Z',s]) for s in count)
                        if match == 'word_slots_and_left':
                            assert incoming_delta == 0
                        calculator = Score(trial_text)
                        row = {
                            'language':lang, 'partition':partition, 'target':target, 'decoy':decoy,
                            'matching':match, 'fraction_of_matched_pool':num/den, 'n_pairs':len(used),
                            'pool':len(paired), 'source_target_occurrences':text.count(target),
                            'source_decoy_occurrences':text.count(decoy), 'characters':len(trial_text),
                            'incoming_count_L1':incoming_delta, 'outgoing_count_L1':outgoing_delta,
                            'scores':{},
                        }
                        for version in ('literal','prose'):
                            ranks = calculator.ranker(version)
                            paired_scores = {symbol:ranks((symbol,*target)) for symbol in ('X','Z')}
                            if match == 'word_slots_and_left':
                                assert paired_scores['X'] == paired_scores['Z']
                            row['scores'][version] = paired_scores
                        rows.append(row)
                        if partition == 'control' and num == den and index == 0 and match == 'word_slots':
                            surrogate = euler_surrogate(trial_text,7073)
                            comparator = Score(surrogate)
                            for version in ('literal','prose'):
                                original = calculator.ranker(version)
                                new = comparator.ranker(version)
                                assert original(('X',*target)) == new(('X',*target))
                                losses = [calculator.total(t,version) for t in product(calculator.alphabet,repeat=3)
                                          if t[0] not in t[1:]]
                                other = [comparator.total(t,version) for t in product(comparator.alphabet,repeat=3)
                                         if t[0] not in t[1:]]
                                assert losses == other
                            euler.append({'language':lang,'target':target, 'identical_triplet_losses':len(losses),
                                          'fraction_changed_slots':sum(x!=y for x,y in zip(trial_text,surrogate))/len(trial_text),
                                          'length':len(trial_text)})
    return rows,euler


def manuscript():
    out = {}
    for name in ('zl','it'):
        partitions = {}
        for part,pages in zip(('train','evaluation'),corpus.split_pages('practice',name)):
            text = ' '.join(word for page in pages for line in page.lines if line.unit == 'P'
                            for word in line.words if word.isascii() and word.isalpha())
            options = {}
            for single_loss in (0.0,1.0):
                calc = Score(text,single_context_loss=single_loss)
                versions = {}
                for version in ('literal','prose'):
                    lookup = calc.ranker(version)
                    versions[version] = {'|'.join(t):lookup(t) for t in DRAFT_TRIPLETS}
                options[str(single_loss)] = versions
            partitions[part] = {'length':len(text), 'singleton_context_loss':options}
        out[name] = partitions
    return out


def clean_lines(pages):
    return [' '.join(word for word in line.words if word.isascii() and word.isalpha())
            for page in pages for line in page.lines if line.unit == 'P']


def stationary_chain():
    results = {}
    for edition in ('zl','it'):
        train,test = corpus.split_pages('practice',edition)
        source = [line for line in clean_lines(train) if line]
        lengths = [len(line) for line in clean_lines(test) if line]
        starts = [line[0] for line in source]
        outgoing = defaultdict(list)
        for line in source:
            for a,b in zip(line,line[1:]):
                outgoing[a].append(b)
        end_neighbors = {a:[b for b in next_symbols if b != ' ']
                         for a,next_symbols in outgoing.items()}
        cases = []
        for seed in range(7810,7816):
            rng = random.Random(seed)
            lines = []
            for length in lengths:
                glyphs = [rng.choice(starts)]
                for i in range(1,length):
                    table = end_neighbors if i == length-1 else outgoing
                    glyphs.append(rng.choice(table.get(glyphs[-1]) or starts))
                lines.append(''.join(glyphs))
            assert [len(line) for line in lines] == lengths
            text = ' '.join(lines)
            assert '  ' not in text
            calc = Score(text)
            measurements = {}
            for version in ('literal','prose'):
                rank = calc.ranker(version)
                measurements[version] = {'|'.join(t):rank(t) for t in DRAFT_TRIPLETS}
            cases.append({'seed':seed,'length':len(text),'measurements':measurements})
        results[edition] = cases
    return results


def summarize(rows):
    summary = {}
    for name in ('word_slots','word_slots_and_left'):
        group = [r for r in rows if r['matching'] == name]
        by_version = {}
        for version in ('literal','prose'):
            counts = {}
            for fraction in (0.25,0.5,1.0):
                candidates = [row['scores'][version] for row in group if row['fraction_of_matched_pool'] == fraction]
                eligible = [pair for pair in candidates if pair['X']['competing'] and pair['Z']['competing']]
                tally = Counter()
                for pair in eligible:
                    x,z = pair['X'],pair['Z']
                    tally['genuine_lower' if x['loss'] < z['loss']-1e-12 else
                          'decoy_lower' if z['loss'] < x['loss']-1e-12 else 'tied'] += 1
                    tally['both_below_5pct'] += x['rank'] <= THRESHOLD and z['rank'] <= THRESHOLD
                    tally['genuine_below_5pct'] += x['rank'] <= THRESHOLD
                counts[fraction] = {'eligible':len(eligible),'all':len(candidates),**tally}
            by_version[version] = counts
        summary[name] = by_version
    return summary


if __name__ == '__main__':
    pairs,exact_bigrams = fixed_match_tests()
    print(json.dumps({'summary':summarize(pairs),'same_bigram_surrogates':exact_bigrams,
                      'manuscript':manuscript(),'stationary_chain':stationary_chain(),'paired_runs':pairs}, indent=2))

