"""Independent entropy-form and cumulative-sampling audit of frozen results."""
import bisect
import hashlib
import json
import math
import random
from collections import Counter, defaultdict
from itertools import accumulate
from pathlib import Path

from vs import refcorpus
import right_context as experiment

ROOT = Path(__file__).resolve().parent


def entropy(probabilities):
    return -math.fsum(p * math.log2(p) for p in probabilities if p)


def entropy_js(counts_p, counts_q):
    alphabet = sorted(counts_p.keys() | counts_q.keys())
    p = [counts_p[s] / sum(counts_p.values()) for s in alphabet]
    q = [counts_q[s] / sum(counts_q.values()) for s in alphabet]
    return entropy([(x+y)/2 for x, y in zip(p, q)]) - (entropy(p)+entropy(q))/2


def contexts(text, symbol, direction):
    # Find symbol positions rather than tabulating adjacent pairs with zip.
    return Counter(text[i+direction] for i, c in enumerate(text)
                   if c == symbol and 0 <= i+direction < len(text))


def score(text, candidate, a, b):
    left = entropy_js(contexts(text, candidate, -1), contexts(text, a, -1))
    right = entropy_js(contexts(text, candidate, 1), contexts(text, b, 1))
    return {'left_js': left, 'bilateral_js': (left+right)/2}


def verify_pair_rows(result):
    checked, maximum = 0, 0
    texts = {}
    for row in result['paired_rows']:
        if not row.get('pairs'):
            continue
        key = row['language'], row['partition']
        if key not in texts:
            texts[key] = experiment.source(*key)
        text = texts[key]
        pool = experiment.matching_pool(text, row['target'], row['decoy'], row['mode'], row['seed'])
        pairs = pool[:len(pool)//2] if row['fraction'] == .5 else pool
        encoded = experiment.plant(text, pairs)
        for candidate in ('X', 'Z'):
            actual = score(encoded, candidate, *row['target'])
            for method, value in actual.items():
                error = abs(value-row['scores'][candidate][method])
                maximum = max(error, maximum)
                assert error < 2e-14, (row, candidate, method, error)
                cutoff = result['thresholds'][method]
                assert experiment.accepted(value, cutoff) == experiment.accepted(row['scores'][candidate][method], cutoff)
                checked += 1
    return checked, maximum


def tables_for(text):
    outgoing = defaultdict(Counter)
    for i in range(len(text)-1):
        outgoing[text[i]][text[i+1]] += 1
    def table(counts):
        symbols = sorted(counts)
        return symbols, list(accumulate(counts[s] for s in symbols))
    starts = table(Counter(w[0] for w in text.split()))
    normal = {c: table(counts) for c, counts in outgoing.items()}
    final = {c: table({s: n for s, n in counts.items() if s != ' '})
             for c, counts in outgoing.items()}
    return starts, normal, final


def direct_text(seed, tables):
    starts, normal, final = tables
    rng = random.Random(seed)
    def draw(table):
        symbols, cumulative = table
        return symbols[bisect.bisect_right(cumulative, rng.randrange(cumulative[-1]))]
    chars = [draw(starts)]
    for i in range(1, 40000):
        table = (final if i == 39999 else normal).get(chars[-1])
        chars.append(draw(table if table and table[0] else starts))
    return ''.join(chars)


def verify_negatives(result):
    checked, maximum = 0, 0
    streams, tables = {}, {}
    for row in result['negative_controls']:
        language, origin, sample = row['language'], row['origin'], row['sample']
        key = language, origin, sample
        if key not in streams:
            if origin == 'natural':
                streams[key] = experiment.source(language, 'evaluation')
            else:
                if language not in tables:
                    tables[language] = tables_for(experiment.source(language, 'training').strip())
                streams[key] = direct_text(sample, tables[language])
        text = streams[key]
        assert hashlib.sha256(text.encode()).hexdigest() == row['sha256']
        for candidate in row['candidates']:
            actual = score(text, candidate['candidate'], *row['target'])
            for method, value in actual.items():
                error = abs(value-candidate['scores'][method])
                maximum = max(error, maximum)
                assert error < 2e-14, (key, row['target'], candidate, error)
                assert experiment.accepted(value, result['thresholds'][method]) == candidate['accepted'][method]
                checked += 1
    return checked, maximum, len(streams)


def main():
    calibration = json.loads((ROOT/'calibration.json').read_bytes())
    evaluation = json.loads((ROOT/'evaluation.json').read_bytes())
    p1, e1 = verify_pair_rows(calibration)
    p2, e2 = verify_pair_rows(evaluation)
    n, e3, samples = verify_negatives(evaluation)
    output = {'paired_js_values_verified': p1+p2, 'negative_js_values_verified': n,
              'distinct_negative_streams_verified': samples,
              'maximum_absolute_js_error': max(e1, e2, e3),
              'all_acceptance_decisions_match': True,
              'all_regenerated_negative_stream_hashes_match': True}
    (ROOT/'verification.json').write_text(json.dumps(output, indent=2))
    print(json.dumps(output, indent=2))


if __name__ == '__main__':
    main()
